// Neutral circle/star at different coordinate scales: identical marks must not
// lose geometry merely because SVGO rounds in user units. Regenerate with:
// node test/fixtures/small-grid.gen.mjs
import { writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

export const gridSvg = (size) => {
  const n = (value) => String(Number((value * size).toPrecision(12)));
  const points = Array.from({ length: 10 }, (_, i) => {
    const angle = -Math.PI / 2 + i * Math.PI / 5, radius = i % 2 ? .18 : .37;
    return `${n(.5 + Math.cos(angle) * radius)},${n(.5 + Math.sin(angle) * radius)}`;
  }).join(' ');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}">\n` +
    `  <circle cx="${n(.5)}" cy="${n(.5)}" r="${n(.4349)}" fill="#17365d"/>\n` +
    `  <polygon points="${points}" fill="#f0c040"/>\n</svg>\n`;
};

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  for (const [name, size] of [['grid-1', 1], ['grid-16', 16], ['grid-24', 24], ['grid-tiny', .001], ['grid-fallback', 1e-12]]) {
    writeFileSync(new URL(`./${name}.svg`, import.meta.url),
      '<!-- Generated by small-grid.gen.mjs: catches scale-dependent SVG rounding. -->\n' + gridSvg(size));
  }
}
